export default [{"id":"2674","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"3","aya_no":"1","aya_text":"قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ","aya_text_emlaey":"قد أفلح المؤمنون","aya_tafseer":"[1] قد فاز المصدِّقون بالله وبرسوله العاملون بشرعه."},{"id":"2675","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"3","aya_no":"2","aya_text":"ٱلَّذِينَ هُمۡ فِي صَلَاتِهِمۡ خَٰشِعُونَ","aya_text_emlaey":"الذين هم في صلاتهم خاشعون","aya_tafseer":"[2] الذين من صفاتهم أنهم في صلاتهم خاشعون، تَفْرُغُ لها قلوبهم، وتسكن جوارحهم."},{"id":"2676","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"4","aya_no":"3","aya_text":"وَٱلَّذِينَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ","aya_text_emlaey":"والذين هم عن اللغو معرضون","aya_tafseer":"[3] والذين هم تاركون لكل ما لا خير فيه من الأقوال والأفعال."},{"id":"2677","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"4","aya_text":"وَٱلَّذِينَ هُمۡ لِلزَّكَوٰةِ فَٰعِلُونَ","aya_text_emlaey":"والذين هم للزكاة فاعلون","aya_tafseer":"[4] والذين هم مُطَهِّرون لنفوسهم وأموالهم بأداء زكاة أموالهم على اختلاف أجناسها."},{"id":"2678","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"5","aya_no":"5","aya_text":"وَٱلَّذِينَ هُمۡ لِفُرُوجِهِمۡ حَٰفِظُونَ","aya_text_emlaey":"والذين هم لفروجهم حافظون","aya_tafseer":"[5] والذين هم لفروجهم حافظون مما حرَّم الله من الزنى واللواط وكل الفواحش."},{"id":"2679","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"6","aya_no":"6","aya_text":"إِلَّا عَلَىٰٓ أَزۡوَٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَإِنَّهُمۡ غَيۡرُ مَلُومِينَ","aya_text_emlaey":"إلا على أزواجهم أو ما ملكت أيمانهم فإنهم غير ملومين","aya_tafseer":"[6] إلا على زوجاتهم أو ما ملكت أيمانهم من الإماء، فلا لوم عليهم ولا حرج في جماعهن والاستمتاع بهن؛ لأن الله تعالى أحلَّهن."},{"id":"2680","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"7","aya_no":"7","aya_text":"فَمَنِ ٱبۡتَغَىٰ وَرَآءَ ذَٰلِكَ فَأُوْلَٰٓئِكَ هُمُ ٱلۡعَادُونَ","aya_text_emlaey":"فمن ابتغى وراء ذلك فأولئك هم العادون","aya_tafseer":"[7] فمن طلب التمتع بغير زوجته أو أمَتِه فهو من المجاوزين الحلال إلى الحرام، وقد عرَّض نفسه لعقاب الله وسخطه."},{"id":"2681","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"8","aya_text":"وَٱلَّذِينَ هُمۡ لِأَمَٰنَٰتِهِمۡ وَعَهۡدِهِمۡ رَٰعُونَ","aya_text_emlaey":"والذين هم لأماناتهم وعهدهم راعون","aya_tafseer":"[8] والذين هم حافظون لكل ما اؤتمنوا عليه، موفُّون بكل عهودهم."},{"id":"2682","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"8","aya_no":"9","aya_text":"وَٱلَّذِينَ هُمۡ عَلَىٰ صَلَوَٰتِهِمۡ يُحَافِظُونَ","aya_text_emlaey":"والذين هم على صلواتهم يحافظون","aya_tafseer":"[9] والذين هم يداومون على أداء صلاتهم في أوقاتها على هيئتها المشروعة، الواردة عن النبي -صلى الله عليه وسلم-."},{"id":"2683","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"9","aya_no":"10","aya_text":"أُوْلَٰٓئِكَ هُمُ ٱلۡوَٰرِثُونَ","aya_text_emlaey":"أولئك هم الوارثون","aya_tafseer":"[10] هؤلاء المؤمنون هم الوارثون الجنة."},{"id":"2684","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"9","aya_no":"11","aya_text":"ٱلَّذِينَ يَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِيهَا خَٰلِدُونَ","aya_text_emlaey":"الذين يرثون الفردوس هم فيها خالدون","aya_tafseer":"[11] الذين يرثون أعلى منازل الجنة وأوسطَها، وهي أفضلُها منزلاً، هم فيها خالدون، لا ينقطع نعيمهم ولا يزول."},{"id":"2685","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"10","aya_no":"12","aya_text":"وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ مِن سُلَٰلَةٖ مِّن طِينٖ","aya_text_emlaey":"ولقد خلقنا الإنسان من سلالة من طين","aya_tafseer":"[12] ولقد خلقنا آدم من طين مأخوذ من جميع الأرض."},{"id":"2686","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"13","aya_text":"ثُمَّ جَعَلۡنَٰهُ نُطۡفَةٗ فِي قَرَارٖ مَّكِينٖ","aya_text_emlaey":"ثم جعلناه نطفة في قرار مكين","aya_tafseer":"[13] ثم خلقنا بنيه متناسلين مِن نطفة: هي مني الرجال تخرج من أصلابهم، فتستقر متمكنة في أرحام النساء."},{"id":"2687","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"13","aya_no":"14","aya_text":"ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةٗ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةٗ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَٰمٗا فَكَسَوۡنَا ٱلۡعِظَٰمَ لَحۡمٗا ثُمَّ أَنشَأۡنَٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَٰلِقِينَ","aya_text_emlaey":"ثم خلقنا النطفة علقة فخلقنا العلقة مضغة فخلقنا المضغة عظاما فكسونا العظام لحما ثم أنشأناه خلقا آخر فتبارك الله أحسن الخالقين","aya_tafseer":"[14] ثم خلقنا النطفة علقة أي: دماً أحمر، فخلقنا العلقة بعد أربعين يوماً مضغة أي: قطعة لحم قَدْر ما يُمْضغ، فخلقنا المضغة اللينة عظاماً، فكسونا العظام لحماً، ثم أنشأناه خلقاً آخر بنفخ الروح فيه، فتبارك الله، الذي أحسن كل شيء خلقه."},{"id":"2688","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"14","aya_no":"15","aya_text":"ثُمَّ إِنَّكُم بَعۡدَ ذَٰلِكَ لَمَيِّتُونَ","aya_text_emlaey":"ثم إنكم بعد ذلك لميتون","aya_tafseer":"[15] ثم إنكم أيها البشر بعد أطوار الحياة وانقضاء الأعمار لَميتون."},{"id":"2689","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"14","line_end":"14","aya_no":"16","aya_text":"ثُمَّ إِنَّكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ تُبۡعَثُونَ","aya_text_emlaey":"ثم إنكم يوم القيامة تبعثون","aya_tafseer":"[16] ثم إنكم بعد الموت وانقضاء الدنيا تُحْيَون يوم القيامة من قبوركم للحساب والجزاء."},{"id":"2690","jozz":"18","page":"342","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"17","aya_text":"وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَآئِقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَٰفِلِينَ","aya_text_emlaey":"ولقد خلقنا فوقكم سبع طرائق وما كنا عن الخلق غافلين","aya_tafseer":"[17] ولقد خلقنا فوقكم سبع سموات بعضها فوق بعض، وما كنا عن الخلق غافلين، فلا نُغْفِلُ مخلوقاً، ولا ننساه."},{"id":"2691","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"2","aya_no":"18","aya_text":"وَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ فَأَسۡكَنَّٰهُ فِي ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَٰدِرُونَ","aya_text_emlaey":"وأنـزلنا من السماء ماء بقدر فأسكناه في الأرض وإنا على ذهاب به لقادرون","aya_tafseer":"[18] وأنزلنا من السماء ماء بقدر حاجة الخلائق، وجعلنا الأرض مستقراً لهذا الماء، وإنا على ذَهاب بالماء المستقر لَقادرون. وفي هذا تهديد ووعيد للظالمين."},{"id":"2692","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"3","aya_no":"19","aya_text":"فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّٰتٖ مِّن نَّخِيلٖ وَأَعۡنَٰبٖ لَّكُمۡ فِيهَا فَوَٰكِهُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ","aya_text_emlaey":"فأنشأنا لكم به جنات من نخيل وأعناب لكم فيها فواكه كثيرة ومنها تأكلون","aya_tafseer":"[19] فأنشأنا بهذا الماء لكم بساتين النخيل والأعناب، لكم فيها فواكه كثيرة الأنواع والأشكال، ومنها تأكلون."},{"id":"2693","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"4","aya_no":"20","aya_text":"وَشَجَرَةٗ تَخۡرُجُ مِن طُورِ سَيۡنَآءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغٖ لِّلۡأٓكِلِينَ","aya_text_emlaey":"وشجرة تخرج من طور سيناء تنبت بالدهن وصبغ للآكلين","aya_tafseer":"[20] وأنشأنا لكم به شجرة الزيتون التي تخرج حول جبل طور «سيناء»، يعصر منها الزيت، فيدَّهن ويؤتدم به."},{"id":"2694","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"6","aya_no":"21","aya_text":"وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهَا وَلَكُمۡ فِيهَا مَنَٰفِعُ كَثِيرَةٞ وَمِنۡهَا تَأۡكُلُونَ","aya_text_emlaey":"وإن لكم في الأنعام لعبرة نسقيكم مما في بطونها ولكم فيها منافع كثيرة ومنها تأكلون","aya_tafseer":"[21] وإن لكم -أيها الناس- في الإبل والبقر والغنم لَعبرة تعتبرون بخلقها، نُسْقيكم مما في بطونها من اللبن، ولكم فيها منافع أخرى كثيرة كالصوف والجلود، ونحوهما، ومنها تأكلون."},{"id":"2695","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"6","aya_no":"22","aya_text":"وَعَلَيۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ","aya_text_emlaey":"وعليها وعلى الفلك تحملون","aya_tafseer":"[22] وعلى الإبل والسفن في البر والبحر تُحْمَلون."},{"id":"2696","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"23","aya_text":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ","aya_text_emlaey":"ولقد أرسلنا نوحا إلى قومه فقال ياقوم اعبدوا الله ما لكم من إله غيره أفلا تتقون","aya_tafseer":"[23] ولقد أرسلنا نوحاً إلى قومه، بدعوة التوحيد فقال لهم: اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جلَّ وعلا، فأخلصوا له العبادة، أفلا تخشون عذابه؟"},{"id":"2697","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"11","aya_no":"24","aya_text":"فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةٗ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ","aya_text_emlaey":"فقال الملأ الذين كفروا من قومه ما هذا إلا بشر مثلكم يريد أن يتفضل عليكم ولو شاء الله لأنـزل ملائكة ما سمعنا بهذا في آبائنا الأولين","aya_tafseer":"[24] فكذَّبه أشراف قومه، وقالوا لعامتهم: إنه إنسان مثلكم لا يتميَّز عنكم بشيء، ولا يريد بقوله إلا رئاسة وفضلاً عليكم، ولو شاء الله أن يرسل إلينا رسولاً لأرسله من الملائكة، ما سمعنا بمثل هذا فيمَن سبقنا من آباء وأجداد."},{"id":"2698","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"11","aya_no":"25","aya_text":"إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةٞ فَتَرَبَّصُواْ بِهِۦ حَتَّىٰ حِينٖ","aya_text_emlaey":"إن هو إلا رجل به جنة فتربصوا به حتى حين","aya_tafseer":"[25] وما نوح إلا رجل به مَسٌّ من الجنون، فانتظروا حتى يُفيق، فيترك دعوته، أو يموت، فتستريحوا منه."},{"id":"2699","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"12","aya_no":"26","aya_text":"قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ","aya_text_emlaey":"قال رب انصرني بما كذبون","aya_tafseer":"[26] قال نوح: رب انصرني على قومي؛ بسبب تكذيبهم إياي فيما بلَّغتهم من رسالتك."},{"id":"2700","jozz":"18","page":"343","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"15","aya_no":"27","aya_text":"فَأَوۡحَيۡنَآ إِلَيۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡيُنِنَا وَوَحۡيِنَا فَإِذَا جَآءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِيهَا مِن كُلّٖ زَوۡجَيۡنِ ٱثۡنَيۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَيۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَٰطِبۡنِي فِي ٱلَّذِينَ ظَلَمُوٓاْ إِنَّهُم مُّغۡرَقُونَ","aya_text_emlaey":"فأوحينا إليه أن اصنع الفلك بأعيننا ووحينا فإذا جاء أمرنا وفار التنور فاسلك فيها من كل زوجين اثنين وأهلك إلا من سبق عليه القول منهم ولا تخاطبني في الذين ظلموا إنهم مغرقون","aya_tafseer":"[27] فأوحينا إليه أن اصنع السفينة بمرأى منا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكِلاءتنا، فإذا جاء أمرنا بعذاب قومك بالغرق، وبدأ الطوفان، فنبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، فأدخِلْ في السفينة من كل الأحياء ذكراً وأنثى؛ ليبقى النسل، وأدخل أهلك إلا مَنِ استحق العذاب لكفره كزوجتك وابنك، ولا تسألني نجاة قومك الظالمين، فإنهم مغرقون لا محالة. وفي هذه الآية إثبات صفة العين لله سبحانه بما يليق به تعالى دون تشبيه ولا تكييف."},{"id":"2701","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"2","aya_no":"28","aya_text":"فَإِذَا ٱسۡتَوَيۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فإذا استويت أنت ومن معك على الفلك فقل الحمد لله الذي نجانا من القوم الظالمين","aya_tafseer":"[28] فإذا علوت السفينة مستقراً عليها أنت ومن معك آمنين من الغرق، فقل: الحمد لله الذي نجَّانا من القوم الكافرين."},{"id":"2702","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"3","aya_no":"29","aya_text":"وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ","aya_text_emlaey":"وقل رب أنـزلني منـزلا مباركا وأنت خير المنـزلين","aya_tafseer":"[29] وقل: رب يَسِّر لي النزول المبارك الآمن، وأنت خير المنزلين. وفي هذا تعليم من الله عز وجل لعباده إذا نزلوا أن يقولوا هذا الدعاء."},{"id":"2703","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"3","aya_no":"30","aya_text":"إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ وَإِن كُنَّا لَمُبۡتَلِينَ","aya_text_emlaey":"إن في ذلك لآيات وإن كنا لمبتلين","aya_tafseer":"[30] إنَّ في إنجاء المؤمنين وإهلاك الكافرين لَدلالات واضحات على صدق رسل الله فيما جاؤوا به من الله، وإن كنا لمختبرين الأمم بإرسال الرسل إليهم قبل وقوع العقوبة بهم."},{"id":"2704","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"4","aya_no":"31","aya_text":"ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِينَ","aya_text_emlaey":"ثم أنشأنا من بعدهم قرنا آخرين","aya_tafseer":"[31] ثم أنشأنا من بعد قوم نوح جيلاً آخر هم قوم عاد."},{"id":"2705","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"32","aya_text":"فَأَرۡسَلۡنَا فِيهِمۡ رَسُولٗا مِّنۡهُمۡ أَنِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ","aya_text_emlaey":"فأرسلنا فيهم رسولا منهم أن اعبدوا الله ما لكم من إله غيره أفلا تتقون","aya_tafseer":"[32] فأرسلنا فيهم رسولاً منهم هو هود عليه السلام، فقال لهم: اعبدوا الله وحده ليس لكم معبود بحق غيره، أفلا تخافون عقابه إذا عبدتم غيره؟"},{"id":"2706","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"8","aya_no":"33","aya_text":"وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِينَ كَفَرُواْ وَكَذَّبُواْ بِلِقَآءِ ٱلۡأٓخِرَةِ وَأَتۡرَفۡنَٰهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا مَا هَٰذَآ إِلَّا بَشَرٞ مِّثۡلُكُمۡ يَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَيَشۡرَبُ مِمَّا تَشۡرَبُونَ","aya_text_emlaey":"وقال الملأ من قومه الذين كفروا وكذبوا بلقاء الآخرة وأترفناهم في الحياة الدنيا ما هذا إلا بشر مثلكم يأكل مما تأكلون منه ويشرب مما تشربون","aya_tafseer":"[33] وقال الأشراف والوجهاء من قومه الذين كفروا بالله، وأنكروا الحياة الآخرة، وأطغاهم ما أُنعم به عليهم في الدنيا من ترف العيش: ما هذا الذي يدعوكم إلى توحيد الله تعالى إلا بشر مثلكم، يأكل من جنس طعامكم، ويشرب من جنس شرابكم."},{"id":"2707","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"8","aya_no":"34","aya_text":"وَلَئِنۡ أَطَعۡتُم بَشَرٗا مِّثۡلَكُمۡ إِنَّكُمۡ إِذٗا لَّخَٰسِرُونَ","aya_text_emlaey":"ولئن أطعتم بشرا مثلكم إنكم إذا لخاسرون","aya_tafseer":"[34] ولئن اتبعتم فرداً مثلكم إنكم إذاً لخاسرون بترككم آلهتكم واتباعكم إياه."},{"id":"2708","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"9","aya_no":"35","aya_text":"أَيَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابٗا وَعِظَٰمًا أَنَّكُم مُّخۡرَجُونَ","aya_text_emlaey":"أيعدكم أنكم إذا متم وكنتم ترابا وعظاما أنكم مخرجون","aya_tafseer":"[35] كيف تُصَدِّقون ما يَعِدُكم به من أنكم إذا متُّم، وصرتم تراباً وعظاماً مفتتة، تُخْرَجون من قبوركم أحياء؟"},{"id":"2709","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"10","aya_no":"36","aya_text":"۞ هَيۡهَاتَ هَيۡهَاتَ لِمَا تُوعَدُونَ","aya_text_emlaey":"هيهات هيهات لما توعدون","aya_tafseer":"[36] بعيد حقّاً ما توعدون به أيها القوم من أنكم بعد موتكم تُخْرَجون أحياء من قبوركم."},{"id":"2710","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"37","aya_text":"إِنۡ هِيَ إِلَّا حَيَاتُنَا ٱلدُّنۡيَا نَمُوتُ وَنَحۡيَا وَمَا نَحۡنُ بِمَبۡعُوثِينَ","aya_text_emlaey":"إن هي إلا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين","aya_tafseer":"[37] ما حياتنا إلا في هذه الدنيا، يموت الآباء منا ويحيا الأبناء، وما نحن بمخرجين أحياء مرة أخرى."},{"id":"2711","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"12","aya_no":"38","aya_text":"إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِينَ","aya_text_emlaey":"إن هو إلا رجل افترى على الله كذبا وما نحن له بمؤمنين","aya_tafseer":"[38] وما هذا الداعي لكم إلى الإيمان إلا رجل اختلق على الله كذباً، ولسنا بمصدقين ما قاله لنا."},{"id":"2712","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"13","aya_no":"39","aya_text":"قَالَ رَبِّ ٱنصُرۡنِي بِمَا كَذَّبُونِ","aya_text_emlaey":"قال رب انصرني بما كذبون","aya_tafseer":"[39] فدعا رسولهم ربه قائلاً: رب انصرني عليهم؛ بسبب تكذيبهم لي."},{"id":"2713","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"13","aya_no":"40","aya_text":"قَالَ عَمَّا قَلِيلٖ لَّيُصۡبِحُنَّ نَٰدِمِينَ","aya_text_emlaey":"قال عما قليل ليصبحن نادمين","aya_tafseer":"[40] وقال الله مجيباً لدعوته: عَمَّا قليل ليصبحُنَّ نادمين، أي: بعد زمن قريب سيصير هؤلاء المكذبون نادمين."},{"id":"2714","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"14","line_end":"15","aya_no":"41","aya_text":"فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَٰهُمۡ غُثَآءٗۚ فَبُعۡدٗا لِّلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"فأخذتهم الصيحة بالحق فجعلناهم غثاء فبعدا للقوم الظالمين","aya_tafseer":"[41] ولم يلبثوا أن جاءتهم صيحة شديدة مع ريح، أهلكهم الله بها، فماتوا جميعاً، وأصبحوا كغثاء السيل الذي يطفو على الماء، فهلاكاً لهؤلاء الظالمين وبُعْداً لهم من رحمة الله. فليحذر السامعون أن يكذبوا رسولهم، فيحل بهم ما حل بسابقيهم."},{"id":"2715","jozz":"18","page":"344","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"42","aya_text":"ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِينَ","aya_text_emlaey":"ثم أنشأنا من بعدهم قرونا آخرين","aya_tafseer":"[42] ثم أنشأنا من بعد هؤلاء المكذبين أمماً وخلائق آخرين كأقوام: لوط وشعيب وأيوب ويونس صلوات الله وسلامه عليهم أجمعين."},{"id":"2716","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"1","aya_no":"43","aya_text":"مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا يَسۡتَـٔۡخِرُونَ","aya_text_emlaey":"ما تسبق من أمة أجلها وما يستأخرون","aya_tafseer":"[43] ما تتقدم أي أمة من هذه الأمم المكذبة الوقت المحدد لهلاكها، ولا تتأخر عنه."},{"id":"2717","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"3","aya_no":"44","aya_text":"ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَآءَ أُمَّةٗ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضٗا وَجَعَلۡنَٰهُمۡ أَحَادِيثَۚ فَبُعۡدٗا لِّقَوۡمٖ لَّا يُؤۡمِنُونَ","aya_text_emlaey":"ثم أرسلنا رسلنا تترى كل ما جاء أمة رسولها كذبوه فأتبعنا بعضهم بعضا وجعلناهم أحاديث فبعدا لقوم لا يؤمنون","aya_tafseer":"[44] ثم أرسلنا رسلنا إلى تلك الأمم يتبع بعضهم بعضاً، كلما دعا رسول أمته كذبوه، فأتبعنا بعضهم بعضاً بالهلاك والدمار، ولم يَبْقَ إلا أخبار هلاكهم، وجعلناها أحاديث لمن بعدهم، يتخذونها عبرة، فهلاكاً وسُحْقاً لقوم لا يصدقون الرسل ولا يطيعونهم."},{"id":"2718","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"4","aya_no":"45","aya_text":"ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَٰرُونَ بِـَٔايَٰتِنَا وَسُلۡطَٰنٖ مُّبِينٍ","aya_text_emlaey":"ثم أرسلنا موسى وأخاه هارون بآياتنا وسلطان مبين","aya_tafseer":"[45] ثم أرسلنا موسى وأخاه هارون بآياتنا التسع وهي: العصا واليد والجراد والقُمَّل والضفادع والدم والطوفان والسنون ونقص من الثمرات، حجةً بيِّنة تقهر القلوب فتنقاد لها قلوب المؤمنين، وتقوم الحجة على المعاندين،"},{"id":"2719","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"46","aya_text":"إِلَىٰ فِرۡعَوۡنَ وَمَلَإِيْهِۦ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمًا عَالِينَ","aya_text_emlaey":"إلى فرعون وملئه فاستكبروا وكانوا قوما عالين","aya_tafseer":"[46] أرسلناهما إلى فرعون حاكم «مصر» وأشراف قومه، فاستكبروا عن الإيمان بموسى وأخيه، وكانوا قوماً متطاولين على الناس قاهرين لهم بالظلم."},{"id":"2720","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"6","aya_no":"47","aya_text":"فَقَالُوٓاْ أَنُؤۡمِنُ لِبَشَرَيۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَٰبِدُونَ","aya_text_emlaey":"فقالوا أنؤمن لبشرين مثلنا وقومهما لنا عابدون","aya_tafseer":"[47] فقالوا: أنصدِّق فَرْدَيْن مثلنا، وقومهما من بني إسرائيل تحت إمرتنا مطيعون متذللون لنا؟"},{"id":"2721","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"6","aya_no":"48","aya_text":"فَكَذَّبُوهُمَا فَكَانُواْ مِنَ ٱلۡمُهۡلَكِينَ","aya_text_emlaey":"فكذبوهما فكانوا من المهلكين","aya_tafseer":"[48] فكذَّبوهما فيما جاءا به، فكانوا من المهلكين بالغرق في البحر."},{"id":"2722","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"7","aya_no":"49","aya_text":"وَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ لَعَلَّهُمۡ يَهۡتَدُونَ","aya_text_emlaey":"ولقد آتينا موسى الكتاب لعلهم يهتدون","aya_tafseer":"[49] ولقد آتينا موسى التوراة؛ ليهتدي بها قومه إلى الحق."},{"id":"2723","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"50","aya_text":"وَجَعَلۡنَا ٱبۡنَ مَرۡيَمَ وَأُمَّهُۥٓ ءَايَةٗ وَءَاوَيۡنَٰهُمَآ إِلَىٰ رَبۡوَةٖ ذَاتِ قَرَارٖ وَمَعِينٖ","aya_text_emlaey":"وجعلنا ابن مريم وأمه آية وآويناهما إلى ربوة ذات قرار ومعين","aya_tafseer":"[50] وجعلنا عيسى بن مريم وأمَّه علامة دالة على قدرتنا؛ إذ خلقناه من غير أب، وجعلنا لهما مأوى في مكان مرتفع من الأرض، مستوٍ للاستقرار عليه، فيه خصوبة وماء جار ظاهر للعيون."},{"id":"2724","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"10","aya_no":"51","aya_text":"يَٰٓأَيُّهَا ٱلرُّسُلُ كُلُواْ مِنَ ٱلطَّيِّبَٰتِ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ عَلِيمٞ","aya_text_emlaey":"ياأيها الرسل كلوا من الطيبات واعملوا صالحا إني بما تعملون عليم","aya_tafseer":"[51] يا أيها الرسل كلوا من طيب الرزق الحلال، واعملوا الأعمال الصالحة، إني بما تعملون عليم، لا يخفى عليَّ شيء من أعمالكم. والخطاب في الآية عام للرسل -عليهم السلام- وأتباعهم، وفي الآية دليل على أن أكل الحلال عون على العمل الصالح، وأن عاقبة الحرام وخيمة، ومنها رد الدعاء."},{"id":"2725","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"52","aya_text":"وَإِنَّ هَٰذِهِۦٓ أُمَّتُكُمۡ أُمَّةٗ وَٰحِدَةٗ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ","aya_text_emlaey":"وإن هذه أمتكم أمة واحدة وأنا ربكم فاتقون","aya_tafseer":"[52] وإنَّ دينكم -يا معشر الأنبياء- دين واحد وهو الإسلام، وأنا ربكم فاتقوني بامتثال أوامري واجتناب زواجري."},{"id":"2726","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"12","aya_no":"53","aya_text":"فَتَقَطَّعُوٓاْ أَمۡرَهُم بَيۡنَهُمۡ زُبُرٗاۖ كُلُّ حِزۡبِۭ بِمَا لَدَيۡهِمۡ فَرِحُونَ","aya_text_emlaey":"فتقطعوا أمرهم بينهم زبرا كل حزب بما لديهم فرحون","aya_tafseer":"[53] فتفرَّق الأتباع في الدين إلى أحزاب وشيع، جعلوا دينهم أدياناً بعدما أُمروا بالاجتماع، كل حزب معجب برأيه زاعم أنه على الحق وغيرَه على الباطل. وفي هذا تحذير من التحزب والتفرق في الدين."},{"id":"2727","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"12","aya_no":"54","aya_text":"فَذَرۡهُمۡ فِي غَمۡرَتِهِمۡ حَتَّىٰ حِينٍ","aya_text_emlaey":"فذرهم في غمرتهم حتى حين","aya_tafseer":"[54] فاتركهم -أيها الرسول- في ضلالتهم وجَهْلهم بالحق إلى أن ينزل العذاب بهم."},{"id":"2728","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"13","aya_no":"55","aya_text":"أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ","aya_text_emlaey":"أيحسبون أنما نمدهم به من مال وبنين","aya_tafseer":"[55] أيظن هؤلاء الكفار أن ما نمدُّهم به من أموال وأولاد في الدنيا هو تعجيلُ خيرٍ لهم يستحقونه؟"},{"id":"2729","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"13","aya_no":"56","aya_text":"نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ بَل لَّا يَشۡعُرُونَ","aya_text_emlaey":"نسارع لهم في الخيرات بل لا يشعرون","aya_tafseer":"[56] إنما نعجل لهم الخير فتنة لهم واستدراجاً، ولكنهم لا يُحِسُّون بذلك."},{"id":"2730","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"14","line_end":"14","aya_no":"57","aya_text":"إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ","aya_text_emlaey":"إن الذين هم من خشية ربهم مشفقون","aya_tafseer":"[57] إنَّ الذين هم من خشية ربهم مشفقون وَجِلون مما خوَّفهم الله تعالى به."},{"id":"2731","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"14","line_end":"15","aya_no":"58","aya_text":"وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ","aya_text_emlaey":"والذين هم بآيات ربهم يؤمنون","aya_tafseer":"[58] والذين هم يصدِّقون بآيات الله في القرآن، ويعملون بها."},{"id":"2732","jozz":"18","page":"345","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"59","aya_text":"وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ","aya_text_emlaey":"والذين هم بربهم لا يشركون","aya_tafseer":"[59] والذين هم يخلصون العبادة لله وحده، ولا يشركون به غيره."},{"id":"2733","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"1","aya_no":"60","aya_text":"وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ","aya_text_emlaey":"والذين يؤتون ما آتوا وقلوبهم وجلة أنهم إلى ربهم راجعون","aya_tafseer":"[60] والذين يجتهدون في أعمال الخير والبر، وقلوبهم خائفة ألَّا تُقبل أعمالهم، وألا تنجيهم من عذاب ربهم إذا رجعوا إليه للحساب."},{"id":"2734","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"2","aya_no":"61","aya_text":"أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ","aya_text_emlaey":"أولئك يسارعون في الخيرات وهم لها سابقون","aya_tafseer":"[61] أولئك المجتهدون في الطاعة، دأبهم المسارعة إلى كل عمل صالح، وهم إلى الخيرات سابقون."},{"id":"2735","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"3","aya_no":"62","aya_text":"وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَيۡنَا كِتَٰبٞ يَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"ولا نكلف نفسا إلا وسعها ولدينا كتاب ينطق بالحق وهم لا يظلمون","aya_tafseer":"[62] ولا نكلف عبداً من عبادنا إلا بما يسعه العمل به، وأعمالهم مسطورة عندنا في كتاب إحصاء الأعمال الذي ترفعه الملائكة ينطق بالحق عليهم، ولا يُظْلم أحد منهم."},{"id":"2736","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"63","aya_text":"بَلۡ قُلُوبُهُمۡ فِي غَمۡرَةٖ مِّنۡ هَٰذَا وَلَهُمۡ أَعۡمَٰلٞ مِّن دُونِ ذَٰلِكَ هُمۡ لَهَا عَٰمِلُونَ","aya_text_emlaey":"بل قلوبهم في غمرة من هذا ولهم أعمال من دون ذلك هم لها عاملون","aya_tafseer":"[63] لكن قلوب الكفار في ضلال غامر عن هذا القرآن وما فيه، ولهم مع شركهم أعمال سيئة، يُمْهلهم الله ليعملوها، فينالوا غضب الله وعقابه."},{"id":"2737","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"6","aya_no":"64","aya_text":"حَتَّىٰٓ إِذَآ أَخَذۡنَا مُتۡرَفِيهِم بِٱلۡعَذَابِ إِذَا هُمۡ يَجۡـَٔرُونَ","aya_text_emlaey":"حتى إذا أخذنا مترفيهم بالعذاب إذا هم يجأرون","aya_tafseer":"[64] حتى إذا أخذنا المترفين وأهل البطر منهم بعذابنا، إذا هم يرفعون أصواتهم يتضرعون مستغيثين."},{"id":"2738","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"6","aya_no":"65","aya_text":"لَا تَجۡـَٔرُواْ ٱلۡيَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ","aya_text_emlaey":"لا تجأروا اليوم إنكم منا لا تنصرون","aya_tafseer":"[65] فيقال لهم: لا تصرخوا ولا تستغيثوا اليوم، إنكم لا تستطيعون نصر أنفسكم، ولا ينصركم أحد من عذاب الله."},{"id":"2739","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"7","aya_no":"66","aya_text":"قَدۡ كَانَتۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُمۡ عَلَىٰٓ أَعۡقَٰبِكُمۡ تَنكِصُونَ","aya_text_emlaey":"قد كانت آياتي تتلى عليكم فكنتم على أعقابكم تنكصون","aya_tafseer":"[66] قد كانت آيات القرآن تُقرأ عليكم؛ لتؤمنوا بها، فكنتم تنفرون من سماعها والتصديق بها، والعمل بها كما يفعل الناكص على عقبيه برجوعه إلى الوراء."},{"id":"2740","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"8","aya_no":"67","aya_text":"مُسۡتَكۡبِرِينَ بِهِۦ سَٰمِرٗا تَهۡجُرُونَ","aya_text_emlaey":"مستكبرين به سامرا تهجرون","aya_tafseer":"[67] تفعلون ذلك مستكبرين على الناس بغير الحق بسبب بيت الله الحرام، تقولون: نحن أهله لا نُغْلَب فيه، وتتسامرون حوله بالسيِّئ من القول."},{"id":"2741","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"9","aya_no":"68","aya_text":"أَفَلَمۡ يَدَّبَّرُواْ ٱلۡقَوۡلَ أَمۡ جَآءَهُم مَّا لَمۡ يَأۡتِ ءَابَآءَهُمُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"أفلم يدبروا القول أم جاءهم ما لم يأت آباءهم الأولين","aya_tafseer":"[68] أفلم يتفكروا في القرآن فيعرفوا صدقه، أم منعهم من الإيمان أنه جاءهم رسول وكتاب لم يأت آباءهم الأولين مثله، فأنكروه وأعرضوا عنه؟"},{"id":"2742","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"10","aya_no":"69","aya_text":"أَمۡ لَمۡ يَعۡرِفُواْ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ","aya_text_emlaey":"أم لم يعرفوا رسولهم فهم له منكرون","aya_tafseer":"[69] أم منعهم من اتباع الحق أن رسولهم محمداً -صلى الله عليه وسلم- غير معروف عندهم، فهم منكرون له؟"},{"id":"2743","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"70","aya_text":"أَمۡ يَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَآءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَٰرِهُونَ","aya_text_emlaey":"أم يقولون به جنة بل جاءهم بالحق وأكثرهم للحق كارهون","aya_tafseer":"[70] بل أحسبوه مجنوناً؟ لقد كذَبوا؛ فإنما جاءهم بالقرآن والتوحيد والدين الحق، وأكثرهم كارهون للحق حسداً وبغياً."},{"id":"2744","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"13","aya_no":"71","aya_text":"وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَآءَهُمۡ لَفَسَدَتِ ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ بَلۡ أَتَيۡنَٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ","aya_text_emlaey":"ولو اتبع الحق أهواءهم لفسدت السموات والأرض ومن فيهن بل أتيناهم بذكرهم فهم عن ذكرهم معرضون","aya_tafseer":"[71] ولو شرع الله لهم ما يوافق أهواءهم لفسدت السموات والأرض ومَن فيهن، بل أتيناهم بما فيه عزهم وشرفهم، وهو القرآن، فهم عنه معرضون."},{"id":"2745","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"14","aya_no":"72","aya_text":"أَمۡ تَسۡـَٔلُهُمۡ خَرۡجٗا فَخَرَاجُ رَبِّكَ خَيۡرٞۖ وَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ","aya_text_emlaey":"أم تسألهم خرجا فخراج ربك خير وهو خير الرازقين","aya_tafseer":"[72] بل أَمَنعهم من الإيمان أنك -أيها الرسول- تسألهم أجراً على دعوتك لهم فبخلوا؟ لم تفعل ذلك، فإن ما عند الله من الثواب والعطاء خير، وهو خير الرازقين، فلا يَقدر أحد أن يَرزق مثل رزقه سبحانه وتعالى."},{"id":"2746","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"14","line_end":"14","aya_no":"73","aya_text":"وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"وإنك لتدعوهم إلى صراط مستقيم","aya_tafseer":"[73] وإنك –أيها الرسول- لتدعو قومك وغيرهم إلى دينٍ قويم، وهو دين الإسلام."},{"id":"2747","jozz":"18","page":"346","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"74","aya_text":"وَإِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ عَنِ ٱلصِّرَٰطِ لَنَٰكِبُونَ","aya_text_emlaey":"وإن الذين لا يؤمنون بالآخرة عن الصراط لناكبون","aya_tafseer":"[74] وإن الذين لا يُصَدِّقون بالبعث والحساب، ولا يعملون لهما، عن طريق الدين القويم لمائلون إلى غيره."},{"id":"2748","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"2","aya_no":"75","aya_text":"۞ وَلَوۡ رَحِمۡنَٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرّٖ لَّلَجُّواْ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ","aya_text_emlaey":"ولو رحمناهم وكشفنا ما بهم من ضر للجوا في طغيانهم يعمهون","aya_tafseer":"[75] ولو رحمناهم وكشفنا عنهم ما بهم مِن قحط وجوع لَتمادَوا في الكفر والعناد، يتحيَّرون ويتخبطون."},{"id":"2749","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"3","aya_no":"76","aya_text":"وَلَقَدۡ أَخَذۡنَٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُواْ لِرَبِّهِمۡ وَمَا يَتَضَرَّعُونَ","aya_text_emlaey":"ولقد أخذناهم بالعذاب فما استكانوا لربهم وما يتضرعون","aya_tafseer":"[76] ولقد ابتليناهم بصنوف المصائب فما خضعوا لربهم، وما دعوه خاشعين عند نزولها."},{"id":"2750","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"4","aya_no":"77","aya_text":"حَتَّىٰٓ إِذَا فَتَحۡنَا عَلَيۡهِم بَابٗا ذَا عَذَابٖ شَدِيدٍ إِذَا هُمۡ فِيهِ مُبۡلِسُونَ","aya_text_emlaey":"حتى إذا فتحنا عليهم بابا ذا عذاب شديد إذا هم فيه مبلسون","aya_tafseer":"[77] حتى إذا فتحنا عليهم باباً من العذاب الشديد في الآخرة، إذا هم فيه آيسون من كل خير، متحيرون لا يدرون ما يصنعون."},{"id":"2751","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"78","aya_text":"وَهُوَ ٱلَّذِيٓ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِيلٗا مَّا تَشۡكُرُونَ","aya_text_emlaey":"وهو الذي أنشأ لكم السمع والأبصار والأفئدة قليلا ما تشكرون","aya_tafseer":"[78] وهو الذي أنشأ لكم السمع لإدراك المسموعات، والأبصار لإدراك المرئيات، والأفئدة لتفقهوا بها، ومع ذلك فشكركم لهذه النعم المتوالية عليكم قليل لا يُذْكَر."},{"id":"2752","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"6","aya_no":"79","aya_text":"وَهُوَ ٱلَّذِي ذَرَأَكُمۡ فِي ٱلۡأَرۡضِ وَإِلَيۡهِ تُحۡشَرُونَ","aya_text_emlaey":"وهو الذي ذرأكم في الأرض وإليه تحشرون","aya_tafseer":"[79] وهو الذي خلق جميع الناس في الأرض، وإليه تُحشرون بعد موتكم، فيجازيكم بما عملتم من خير أو شر."},{"id":"2753","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"7","aya_no":"80","aya_text":"وَهُوَ ٱلَّذِي يُحۡيِۦ وَيُمِيتُ وَلَهُ ٱخۡتِلَٰفُ ٱلَّيۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ","aya_text_emlaey":"وهو الذي يحيي ويميت وله اختلاف الليل والنهار أفلا تعقلون","aya_tafseer":"[80] وهو وحده الذي يحيي من العدم، ويميت بعد الحياة، وله تعاقب الليل والنهار وتفاوتهما، أفلا تعقلون قدرته ووحدانيته؟"},{"id":"2754","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"81","aya_text":"بَلۡ قَالُواْ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ","aya_text_emlaey":"بل قالوا مثل ما قال الأولون","aya_tafseer":"[81] لكن الكفار لم يصدقوا بالبعث، بل ردَّدوا مقولة أسلافهم المنكرين."},{"id":"2755","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"9","aya_no":"82","aya_text":"قَالُوٓاْ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗا وَعِظَٰمًا أَءِنَّا لَمَبۡعُوثُونَ","aya_text_emlaey":"قالوا أئذا متنا وكنا ترابا وعظاما أئنا لمبعوثون","aya_tafseer":"[82] قالوا: أإذا متنا وتحللت أجسامنا وعظامنا في تراب الأرض نُحْيا مرة أُخرى؟ هذا لا يكون ولا يُتصور."},{"id":"2756","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"10","aya_no":"83","aya_text":"لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَآؤُنَا هَٰذَا مِن قَبۡلُ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"لقد وعدنا نحن وآباؤنا هذا من قبل إن هذا إلا أساطير الأولين","aya_tafseer":"[83] لقد قيل هذا الكلام لآبائنا من قبل، كما تقوله لنا يا محمد، فلم نره حقيقة، ما هذا إلا أباطيل الأولين."},{"id":"2757","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"84","aya_text":"قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِيهَآ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"قل لمن الأرض ومن فيها إن كنتم تعلمون","aya_tafseer":"[84] قل لهم: لمن هذه الأرض ومَن فيها إن كان لديكم علم؟"},{"id":"2758","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"12","aya_no":"85","aya_text":"سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"سيقولون لله قل أفلا تذكرون","aya_tafseer":"[85] سيعترفون حتماً بأنها لله، هو خالقها ومالكها، قل لهم: ألا يكون لكم في ذلك تذكُّر بأنه قادر على البعث والنشور؟"},{"id":"2759","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"13","aya_no":"86","aya_text":"قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ","aya_text_emlaey":"قل من رب السموات السبع ورب العرش العظيم","aya_tafseer":"[86] قل مَن رب السموات السبع وربُّ العرشِ العظيمِ، الذي جعله اللهُ أعظمَ المخلوقاتِ وأعلاها؟"},{"id":"2760","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"13","aya_no":"87","aya_text":"سَيَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ","aya_text_emlaey":"سيقولون لله قل أفلا تتقون","aya_tafseer":"[87] سيقولون حتماً: هي مِلْك لله، فقل لهم: أفلا تخافون عذابه إذا عبدتم غيره؟"},{"id":"2761","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"15","aya_no":"88","aya_text":"قُلۡ مَنۢ بِيَدِهِۦ مَلَكُوتُ كُلِّ شَيۡءٖ وَهُوَ يُجِيرُ وَلَا يُجَارُ عَلَيۡهِ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"قل من بيده ملكوت كل شيء وهو يجير ولا يجار عليه إن كنتم تعلمون","aya_tafseer":"[88] قل: مَن مالك كل شيء ومَن بيده خزائن كل شيء، ومَن يجير مَنِ استجار به، ولا يقدر أحد أن يُجير ويحمي مَن أراد الله إهلاكه، ولا يدفع الشر الذي قدَّره الله، إن كنتم تعلمون ذلك؟"},{"id":"2762","jozz":"18","page":"347","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"89","aya_text":"سَيَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ","aya_text_emlaey":"سيقولون لله قل فأنى تسحرون","aya_tafseer":"[89] سيجيبون: بأن ذلك كلَّه لله، قل لهم: كيف تذهب عقولكم وتُخْدَعون وتُصْرفون عن توحيد الله وطاعته، وتصديق أمر البعث والنشور؟"},{"id":"2763","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"1","aya_no":"90","aya_text":"بَلۡ أَتَيۡنَٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَٰذِبُونَ","aya_text_emlaey":"بل أتيناهم بالحق وإنهم لكاذبون","aya_tafseer":"[90] بل أتينا هؤلاء المنكرين بالحق فيما أرسلنا به محمداً -صلى الله عليه وسلم-، وإنهم لَكاذبون في شركهم وإنكارهم البعث."},{"id":"2764","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"3","aya_no":"91","aya_text":"مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٖ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَٰهٍۚ إِذٗا لَّذَهَبَ كُلُّ إِلَٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضٖۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ","aya_text_emlaey":"ما اتخذ الله من ولد وما كان معه من إله إذا لذهب كل إله بما خلق ولعلا بعضهم على بعض سبحان الله عما يصفون","aya_tafseer":"[91] لم يجعل الله لنفسه ولداً، ولم يكن معه مِن معبود آخر؛ لأنه لو كان ثمة أكثر مِن معبود لانفرد كل معبود بمخلوقاته، ولكان بينهم مغالبة كشأن ملوك الدنيا، فيختلُّ نظام الكون، تنزَّه الله سبحانه وتعالى وتقدَّس عن وصفهم له بأن له شريكاً أو ولداً."},{"id":"2765","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"4","aya_no":"92","aya_text":"عَٰلِمِ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ فَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","aya_text_emlaey":"عالم الغيب والشهادة فتعالى عما يشركون","aya_tafseer":"[92] هو وحده يعلم ما غاب عن خلقه وما شاهدوه، فتنزَّه الله تعالى عن الشريك الذي يزعمون."},{"id":"2766","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"5","aya_no":"93","aya_text":"قُل رَّبِّ إِمَّا تُرِيَنِّي مَا يُوعَدُونَ","aya_text_emlaey":"قل رب إما تريني ما يوعدون","aya_tafseer":"[93] قل -أيها الرسول-: ربِّ إما ترينِّي في هؤلاء المشركين ما تَعِدُهم مِن عذابك فلا تهلكني بما تهلكهم به، ونجني من عذابك وسخطك،"},{"id":"2767","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"5","line_end":"5","aya_no":"94","aya_text":"رَبِّ فَلَا تَجۡعَلۡنِي فِي ٱلۡقَوۡمِ ٱلظَّٰلِمِينَ","aya_text_emlaey":"رب فلا تجعلني في القوم الظالمين","aya_tafseer":"[94] فلا تجعلني في القوم المشركين الظالمين، ولكن اجعلني ممن رضيتَ عنهم."},{"id":"2768","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"6","aya_no":"95","aya_text":"وَإِنَّا عَلَىٰٓ أَن نُّرِيَكَ مَا نَعِدُهُمۡ لَقَٰدِرُونَ","aya_text_emlaey":"وإنا على أن نريك ما نعدهم لقادرون","aya_tafseer":"[95] وإننا لَقادرون على أن نريك ما نَعِدُهم من العذاب."},{"id":"2769","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"7","aya_no":"96","aya_text":"ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ ٱلسَّيِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا يَصِفُونَ","aya_text_emlaey":"ادفع بالتي هي أحسن السيئة نحن أعلم بما يصفون","aya_tafseer":"[96] إذا أساء إليك أعداؤك -أيها الرسول- بالقول أو الفعل فلا تقابلهم بالإساءة، ولكن ادفع إساءتهم بالإحسان منك إليهم، نحن أعلم بما يصفه هؤلاء المشركون من الشرك والتكذيب، وسنجازيهم عليه أسوأ الجزاء."},{"id":"2770","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"97","aya_text":"وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ","aya_text_emlaey":"وقل رب أعوذ بك من همزات الشياطين","aya_tafseer":"[97] وقل -أيها النبي-: رب أستجير بك من إغواء الشياطين المغرية على الباطل والفساد والصد عن الحق ووسوستها،"},{"id":"2771","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"9","aya_no":"98","aya_text":"وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ","aya_text_emlaey":"وأعوذ بك رب أن يحضرون","aya_tafseer":"[98] وأستجير بك -يا رب- مِن حضورهم في شيء من أموري."},{"id":"2772","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"10","aya_no":"99","aya_text":"حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ","aya_text_emlaey":"حتى إذا جاء أحدهم الموت قال رب ارجعون","aya_tafseer":"[99] يخبر الله تعالى عن حال المحتضر من الكافرين أو المفرطين في أمره تعالى، حتى إذا أشرف على الموت، وشاهد ما أُعِدَّ له من العذاب قال: رب ردُّوني إلى الدنيا."},{"id":"2773","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"11","aya_no":"100","aya_text":"لَعَلِّيٓ أَعۡمَلُ صَٰلِحٗا فِيمَا تَرَكۡتُۚ كَلَّآۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَاۖ وَمِن وَرَآئِهِم بَرۡزَخٌ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","aya_text_emlaey":"لعلي أعمل صالحا فيما تركت كلا إنها كلمة هو قائلها ومن ورائهم برزخ إلى يوم يبعثون","aya_tafseer":"[100] لعلي أستدرك ما ضيَّعْتُ من الإيمان والطاعة. ليس له ذلك، فلا يجاب إلى ما طَلَب، ولا يُمْهَل، فإنما هي كلمة هو قائلها قولاً لا ينفعه، وهو فيه غير صادق، فلو رُدَّ إلى الدنيا لعاد إلى ما نُهي عنه، وسيبقى المتوفَّون في الحاجز والبَرْزخ الذي بين الدنيا والآخرة إلى يوم البعث والنشور."},{"id":"2774","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"12","aya_no":"101","aya_text":"فَإِذَا نُفِخَ فِي ٱلصُّورِ فَلَآ أَنسَابَ بَيۡنَهُمۡ يَوۡمَئِذٖ وَلَا يَتَسَآءَلُونَ","aya_text_emlaey":"فإذا نفخ في الصور فلا أنساب بينهم يومئذ ولا يتساءلون","aya_tafseer":"[101] فإذا كان يوم القيامة، ونفخ المَلَك المكلَّف في «القَرْن»، وبُعِثَ الناس من قبورهم، فلا تَفاخُرَ بالأنساب حينئذ كما كانوا يفتخرون بها في الدنيا، ولا يسأل أحد أحداً."},{"id":"2775","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"13","aya_no":"102","aya_text":"فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","aya_text_emlaey":"فمن ثقلت موازينه فأولئك هم المفلحون","aya_tafseer":"[102] فمن كثرت حسناته وثَقُلَتْ بها موازين أعماله عند الحساب، فأولئك هم الفائزون بالجنة."},{"id":"2776","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"15","aya_no":"103","aya_text":"وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ فِي جَهَنَّمَ خَٰلِدُونَ","aya_text_emlaey":"ومن خفت موازينه فأولئك الذين خسروا أنفسهم في جهنم خالدون","aya_tafseer":"[103] ومن قَلَّتْ حسناته في الميزان، ورجحت سيئاته، وأعظمها الشرك، فأولئك هم الذين خابوا وخسروا أنفسهم، في نار جهنم خالدون."},{"id":"2777","jozz":"18","page":"348","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"104","aya_text":"تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِيهَا كَٰلِحُونَ","aya_text_emlaey":"تلفح وجوههم النار وهم فيها كالحون","aya_tafseer":"[104] تَحْرقُ النار وجوههم، وهم فيها عابسون تَقَلَّصَتْ شفاههم، وبرزت أسنانهم."},{"id":"2778","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"1","line_end":"1","aya_no":"105","aya_text":"أَلَمۡ تَكُنۡ ءَايَٰتِي تُتۡلَىٰ عَلَيۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ","aya_text_emlaey":"ألم تكن آياتي تتلى عليكم فكنتم بها تكذبون","aya_tafseer":"[105] يقال لهم: ألم تكن آيات القرآن تتلى عليكم في الدنيا، فكنتم بها تكذبون؟"},{"id":"2779","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"2","line_end":"2","aya_no":"106","aya_text":"قَالُواْ رَبَّنَا غَلَبَتۡ عَلَيۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمٗا ضَآلِّينَ","aya_text_emlaey":"قالوا ربنا غلبت علينا شقوتنا وكنا قوما ضالين","aya_tafseer":"[106] لما بلَّغتهم الرسل وأنذرتهم قالوا يوم القيامة: ربنا غلبت علينا لذاتنا وأهواؤنا المقدَّرة علينا في سابق علمك، وكنا في فعلنا ضالين عن الهدى."},{"id":"2780","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"3","line_end":"3","aya_no":"107","aya_text":"رَبَّنَآ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَٰلِمُونَ","aya_text_emlaey":"ربنا أخرجنا منها فإن عدنا فإنا ظالمون","aya_tafseer":"[107] ربنا أخرجنا من النار، وأعدنا إلى الدنيا، فإن رجعنا إلى الضلال فإنا ظالمون نستحق العقوبة."},{"id":"2781","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"4","aya_no":"108","aya_text":"قَالَ ٱخۡسَـُٔواْ فِيهَا وَلَا تُكَلِّمُونِ","aya_text_emlaey":"قال اخسئوا فيها ولا تكلمون","aya_tafseer":"[108] قال الله عز وجل لهم: امكثوا في النار أذلاء ولا تخاطبوني. فانقطع عند ذلك دعاؤهم ورجاؤهم."},{"id":"2782","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"4","line_end":"6","aya_no":"109","aya_text":"إِنَّهُۥ كَانَ فَرِيقٞ مِّنۡ عِبَادِي يَقُولُونَ رَبَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ","aya_text_emlaey":"إنه كان فريق من عبادي يقولون ربنا آمنا فاغفر لنا وارحمنا وأنت خير الراحمين","aya_tafseer":"[109] إنه كان فريق من عبادي -وهم المؤمنون- يَدْعون: ربنا آمنا فاستر ذنوبنا، وارحمنا، وأنت خير الراحمين."},{"id":"2783","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"6","line_end":"7","aya_no":"110","aya_text":"فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِيًّا حَتَّىٰٓ أَنسَوۡكُمۡ ذِكۡرِي وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ","aya_text_emlaey":"فاتخذتموهم سخريا حتى أنسوكم ذكري وكنتم منهم تضحكون","aya_tafseer":"[110] فاشتغلتم بالاستهزاء بهم حتى نسيتم ذكر الله، فبقيتم على تكذيبكم، وقد كنتم تضحكون منهم سخرية واستهزاء."},{"id":"2784","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"7","line_end":"8","aya_no":"111","aya_text":"إِنِّي جَزَيۡتُهُمُ ٱلۡيَوۡمَ بِمَا صَبَرُوٓاْ أَنَّهُمۡ هُمُ ٱلۡفَآئِزُونَ","aya_text_emlaey":"إني جزيتهم اليوم بما صبروا أنهم هم الفائزون","aya_tafseer":"[111] إني جزيت هذا الفريق من عبادي المؤمنين الفوز بالجنة؛ بسبب صبرهم على الأذى وطاعة الله."},{"id":"2785","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"8","line_end":"9","aya_no":"112","aya_text":"قَٰلَ كَمۡ لَبِثۡتُمۡ فِي ٱلۡأَرۡضِ عَدَدَ سِنِينَ","aya_text_emlaey":"قال كم لبثتم في الأرض عدد سنين","aya_tafseer":"[112] ويُسْألُ الأشقياء في النار: كم بقيتم في الدنيا من السنين؟ وكم ضيَّعتم فيها من طاعة الله؟"},{"id":"2786","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"9","line_end":"9","aya_no":"113","aya_text":"قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖ فَسۡـَٔلِ ٱلۡعَآدِّينَ","aya_text_emlaey":"قالوا لبثنا يوما أو بعض يوم فاسأل العادين","aya_tafseer":"[113] قالوا لِهول الموقف وشدة العذاب: بقينا فيها يوماً أو بعض يوم، فاسأل الحُسَّاب الذين يعدُّون الشهور والأيام."},{"id":"2787","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"10","line_end":"10","aya_no":"114","aya_text":"قَٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"قال إن لبثتم إلا قليلا لو أنكم كنتم تعلمون","aya_tafseer":"[114] قال لهم: ما لبثتم إلا وقتاً قليلاً لو صبرتم فيه على طاعة الله لفزتم بالجنة، لو كان عندكم علم بذلك؛ وذلك لأن مدة مكثهم في الدنيا قليلة جدّاً بالنسبة إلى طول مدتهم خالدين في النار."},{"id":"2788","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"11","line_end":"11","aya_no":"115","aya_text":"أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَٰكُمۡ عَبَثٗا وَأَنَّكُمۡ إِلَيۡنَا لَا تُرۡجَعُونَ","aya_text_emlaey":"أفحسبتم أنما خلقناكم عبثا وأنكم إلينا لا ترجعون","aya_tafseer":"[115] أفحسبتم -أيها الخلق- أنما خلقناكم مهملين، لا أمر ولا نهي ولا ثواب ولا عقاب، وأنكم إلينا لا ترجعون في الآخرة للحساب والجزاء؟"},{"id":"2789","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"12","line_end":"12","aya_no":"116","aya_text":"فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَآ إِلَٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِيمِ","aya_text_emlaey":"فتعالى الله الملك الحق لا إله إلا هو رب العرش الكريم","aya_tafseer":"[116] فتعالى الله الملك المتصرف في كل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكلُّ شيء منه حق، وتَقَدَّس عن أن يخلق شيئاً عبثاً أو سَفَهاً، لا إله غيره ربُّ العرشِ الكريمِ، فعرشُ الرحمن موصوفٌ بالكرم؛ لشَرَفه، والعرشُ أعظمُ المخلوقات."},{"id":"2790","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"13","line_end":"14","aya_no":"117","aya_text":"وَمَن يَدۡعُ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ لَا بُرۡهَٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦٓۚ إِنَّهُۥ لَا يُفۡلِحُ ٱلۡكَٰفِرُونَ","aya_text_emlaey":"ومن يدع مع الله إلها آخر لا برهان له به فإنما حسابه عند ربه إنه لا يفلح الكافرون","aya_tafseer":"[117] ومن يعبد مع الله الواحد إلهاً آخر، لا حجة له على استحقاقه العبادة، فإنما جزاؤه على عمله السيِّئ عند ربه في الآخرة. إنه لا فلاح ولا نجاة للكافرين يوم القيامة."},{"id":"2791","jozz":"18","page":"349","sura_no":"23","sura_name_en":"Al-Mu’minūn","sura_name_ar":"المؤمنُون ","line_start":"15","line_end":"15","aya_no":"118","aya_text":"وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ","aya_text_emlaey":"وقل رب اغفر وارحم وأنت خير الراحمين","aya_tafseer":"[118] وقل -أيها النبي-: ربِّ تجاوَزْ عن الذنوب وارحم؛ وأنت خير مَن رحم ذا ذنب، فقبل توبته ولم يعاقبه على ذنبه."}]
